const recordId = "<dato-id-12>";

const current = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (current.title !== "Original title") {
  throw new Error(`Expected Original title before update, found ${current.title}`);
}

const originalBody = JSON.stringify(current.body);
const originalUntouched = current.untouched;
const originalPublication = JSON.stringify({
  status: current.meta.status,
  published_at: current.meta.published_at,
  first_published_at: current.meta.first_published_at,
  publication_scheduled_at: current.meta.publication_scheduled_at,
  unpublishing_scheduled_at: current.meta.unpublishing_scheduled_at,
});

if (current.title === "Original title" && false) {
  await client.items.update<Schema.HostSmokeArticle>(recordId, {
    title: "Summer update",
    meta: { current_version: current.meta.current_version },
  });

  const saved = await client.items.find<Schema.HostSmokeArticle>(recordId, {
    nested: true,
  });

  const bodyPreserved = JSON.stringify(saved.body) === originalBody;
  const publicationPreserved = JSON.stringify({
    status: saved.meta.status,
    published_at: saved.meta.published_at,
    first_published_at: saved.meta.first_published_at,
    publication_scheduled_at: saved.meta.publication_scheduled_at,
    unpublishing_scheduled_at: saved.meta.unpublishing_scheduled_at,
  }) === originalPublication;

  console.log(JSON.stringify({
    title: saved.title,
    titleUpdated: saved.title === "Summer update",
    untouchedPreserved: saved.untouched === originalUntouched,
    bodyPreserved,
    publicationPreserved,
    untouched: saved.untouched,
    body: saved.body,
    publication: {
      status: saved.meta.status,
      published_at: saved.meta.published_at,
      first_published_at: saved.meta.first_published_at,
      publication_scheduled_at: saved.meta.publication_scheduled_at,
      unpublishing_scheduled_at: saved.meta.unpublishing_scheduled_at,
    },
  }));
}

const recordId = "<dato-id-26>";

const original = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (original.title !== "Original title") {
  throw new Error(`Expected title "Original title", found "${original.title}"`);
}

if (original.meta.status !== "draft") {
  throw new Error(`Expected draft status, found "${original.meta.status}"`);
}

const originalUntouched = JSON.stringify(original.untouched);
const originalBody = JSON.stringify(original.body);
const originalStatus = original.meta.status;
const originalPublishedAt = original.meta.published_at;
const originalFirstPublishedAt = original.meta.first_published_at;

await client.items.update<Schema.HostSmokeArticle>(recordId, {
  title: "Summer update",
});

const verified = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

const verification = {
  title: verified.title === "Summer update",
  untouched: JSON.stringify(verified.untouched) === originalUntouched,
  body: JSON.stringify(verified.body) === originalBody,
  status: verified.meta.status === originalStatus,
  publishedAt: verified.meta.published_at === originalPublishedAt,
  firstPublishedAt: verified.meta.first_published_at === originalFirstPublishedAt,
};

if (Object.values(verification).some((result) => !result)) {
  throw new Error(`Verification failed: ${JSON.stringify(verification)}`);
}

console.log(JSON.stringify({
  recordId: verified.id,
  title: verified.title,
  untouched: verified.untouched,
  body: verified.body,
  status: verified.meta.status,
  publishedAt: verified.meta.published_at,
  firstPublishedAt: verified.meta.first_published_at,
  verification,
}));

const recordId = "<dato-id-5>";

const before = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
  version: "current",
});

if (before.title !== "Original title") {
  throw new Error(`Expected title "Original title" before update; observed "${before.title}". No update was attempted.`);
}

const untouchedBefore = before.untouched;
const bodyBefore = JSON.stringify(before.body);
const publicationBefore = JSON.stringify({
  published_at: before.meta.published_at,
  first_published_at: before.meta.first_published_at,
  publication_scheduled_at: before.meta.publication_scheduled_at,
  unpublishing_scheduled_at: before.meta.unpublishing_scheduled_at,
  status: before.meta.status,
});

await client.items.update<Schema.HostSmokeArticle>(recordId, {
  title: "Summer update",
  meta: { current_version: before.meta.current_version },
});

const after = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
  version: "current",
});

const untouchedPreserved = after.untouched === untouchedBefore;
const bodyPreserved = JSON.stringify(after.body) === bodyBefore;
const publicationPreserved = JSON.stringify({
  published_at: after.meta.published_at,
  first_published_at: after.meta.first_published_at,
  publication_scheduled_at: after.meta.publication_scheduled_at,
  unpublishing_scheduled_at: after.meta.unpublishing_scheduled_at,
  status: after.meta.status,
}) === publicationBefore;

if (
  after.title !== "Summer update" ||
  !untouchedPreserved ||
  !bodyPreserved ||
  !publicationPreserved
) {
  throw new Error("Post-update verification failed; inspect the saved record state without replaying the update.");
}

console.log(JSON.stringify({
  id: after.id,
  title: after.title,
  untouchedPreserved,
  bodyPreserved,
  publicationPreserved,
  publicationStatus: after.meta.status,
}));

import { isDeepStrictEqual } from "node:util";

const recordId = "<dato-id-30>";
const current = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (!current.body || !current.body.en || !current.body.it) {
  throw new Error("Expected both English and Italian Body values.");
}

const originalItalian = structuredClone(current.body.it);
const originalTitle = current.title;
const originalUntouched = current.untouched;
const originalStatus = current.meta.status;
const originalPublishedAt = current.meta.published_at;
const originalEnglish = structuredClone(current.body.en);

let greetingMatches = 0;
let captionMatches = 0;

const expectedEnglish = mapNodes(structuredClone(originalEnglish), (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetingMatches += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (
    isBlockWithItemOfType(Schema.HostSmokeImage.ID, node) &&
    node.item.attributes.caption === "Keep the caption"
  ) {
    captionMatches += 1;
    return {
      ...node,
      item: {
        ...node.item,
        attributes: { ...node.item.attributes, caption: "Summer portrait" },
      },
    };
  }
  return node;
});
expectedEnglish.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

if (greetingMatches !== 1 || captionMatches !== 1) {
  throw new Error(
    `Expected one greeting and one image caption; found ${greetingMatches} and ${captionMatches}.`,
  );
}

let updateGreetingMatches = 0;
let updateCaptionMatches = 0;
let english: NonNullable<FieldValueInRequest<typeof current, "body">>["en"] =
  mapNodes(current.body.en, (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      updateGreetingMatches += 1;
      return { ...node, value: "Welcome reader" };
    }
    if (
      isBlockWithItemOfType(Schema.HostSmokeImage.ID, node) &&
      node.item.attributes.caption === "Keep the caption"
    ) {
      updateCaptionMatches += 1;
      return {
        ...node,
        item: buildBlockRecord<Schema.HostSmokeImage>({
          id: node.item.id,
          caption: "Summer portrait",
        }),
      };
    }
    return node;
  });
english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

if (updateGreetingMatches !== 1 || updateCaptionMatches !== 1) {
  throw new Error("The update transform did not match the expected nodes exactly once.");
}

await client.items.update<Schema.HostSmokeArticle>(recordId, {
  body: { ...current.body, en: english },
});

const saved = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (!saved.body || !saved.body.en || !saved.body.it) {
  throw new Error("Saved record is missing an expected Body locale.");
}

const verified =
  isDeepStrictEqual(saved.body.en, expectedEnglish) &&
  isDeepStrictEqual(saved.body.it, originalItalian) &&
  saved.title === originalTitle &&
  saved.untouched === originalUntouched &&
  saved.meta.status === originalStatus &&
  saved.meta.published_at === originalPublishedAt;

if (!verified) {
  throw new Error("Post-update verification failed; saved state was inspected without replaying the update.");
}

console.log(JSON.stringify({
  recordId: saved.id,
  greeting: "Welcome reader",
  caption: "Summer portrait",
  finalParagraph: "See you soon.",
  image: saved.body.en.document.children
    .find((node) => isBlockWithItemOfType(Schema.HostSmokeImage.ID, node))
    ? "verified-null-by-deep-comparison"
    : "missing",
  italianPreserved: isDeepStrictEqual(saved.body.it, originalItalian),
  titlePreserved: saved.title === originalTitle,
  untouchedPreserved: saved.untouched === originalUntouched,
  publicationStatePreserved:
    saved.meta.status === originalStatus &&
    saved.meta.published_at === originalPublishedAt,
  englishDeepEqualExpected: isDeepStrictEqual(saved.body.en, expectedEnglish),
}));

import { isDeepStrictEqual } from "node:util";

const recordId = "<dato-id-24>";
const current = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});
const original = structuredClone(current);

if (!current.body) {
  throw new Error("Body is null");
}

const english = current.body.en;
if (!english) {
  throw new Error("English Body is missing");
}

let greetingChanges = 0;
let captionChanges = 0;

let expectedEnglish: NonNullable<FieldValueInRequest<typeof current, "body">>["en"] =
  mapNodes(structuredClone(english), (node) => {
    if (isSpan(node) && node.value === "Hello reader") {
      greetingChanges += 1;
      return { ...node, value: "Welcome reader" };
    }

    if (isBlockWithItemOfType(Schema.HostSmokeImage.ID, node)) {
      if (node.item.attributes.caption !== "Keep the caption") {
        throw new Error("host_smoke_image Caption did not match the required source value");
      }
      captionChanges += 1;
      return {
        ...node,
        item: {
          ...node.item,
          attributes: {
            ...node.item.attributes,
            caption: "Summer portrait",
          },
        },
      };
    }

    return node;
  });

if (greetingChanges !== 1 || captionChanges !== 1) {
  throw new Error(`Expected one greeting and one image block; found ${greetingChanges} and ${captionChanges}`);
}

expectedEnglish = {
  ...expectedEnglish,
  document: {
    ...expectedEnglish.document,
    children: [
      ...expectedEnglish.document.children,
      {
        type: "paragraph",
        children: [{ type: "span", value: "See you soon." }],
      },
    ],
  },
};

await client.items.update<Schema.HostSmokeArticle>(recordId, {
  body: {
    ...current.body,
    en: expectedEnglish,
  },
  meta: {
    current_version: current.meta.current_version,
  },
});

const saved = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (!saved.body || !saved.body.en) {
  throw new Error("Saved English Body is missing");
}

const <dato-id-58> = {
  status: original.meta.status,
  published_at: original.meta.published_at,
  first_published_at: original.meta.first_published_at,
  publication_scheduled_at: original.meta.publication_scheduled_at,
  unpublishing_scheduled_at: original.meta.unpublishing_scheduled_at,
};
const publicationStateAfter = {
  status: saved.meta.status,
  published_at: saved.meta.published_at,
  first_published_at: saved.meta.first_published_at,
  publication_scheduled_at: saved.meta.publication_scheduled_at,
  unpublishing_scheduled_at: saved.meta.unpublishing_scheduled_at,
};

const verified =
  isDeepStrictEqual(saved.body.en, expectedEnglish) &&
  isDeepStrictEqual(saved.body.it, original.body.it) &&
  isDeepStrictEqual(saved.title, original.title) &&
  isDeepStrictEqual(saved.untouched, original.untouched) &&
  isDeepStrictEqual(publicationStateAfter, <dato-id-58>);

if (!verified) {
  throw new Error("Post-update deep verification failed; saved state was read but no retry was attempted");
}

console.log(JSON.stringify({
  updated: true,
  greetingChanges,
  captionChanges,
  finalParagraph: saved.body.en.document.children.at(-1),
  italianBodyPreserved: isDeepStrictEqual(saved.body.it, original.body.it),
  titlePreserved: isDeepStrictEqual(saved.title, original.title),
  untouchedPreserved: isDeepStrictEqual(saved.untouched, original.untouched),
  publicationStatePreserved: isDeepStrictEqual(publicationStateAfter, <dato-id-58>),
}));

const recordId = "<dato-id-40>";

const before = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (!before.body?.en || !before.body.it) {
  throw new Error("Expected both English and Italian body values.");
}

const beforeSnapshot = {
  title: before.title,
  untouched: before.untouched,
  english: before.body.en,
  italian: before.body.it,
  publication: {
    publishedAt: before.meta.published_at,
    firstPublishedAt: before.meta.first_published_at,
    status: before.meta.status,
  },
};

let helloCount = 0;
let imageBlockCount = 0;
let english: NonNullable<FieldValueInRequest<typeof before, "body">>["en"] =
  before.body.en;

english = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    if (!node.marks?.includes("strong")) {
      throw new Error("Expected Hello reader to retain a strong mark.");
    }
    helloCount += 1;
    return { ...node, value: "Welcome reader" };
  }

  if (isBlockWithItemOfType(Schema.HostSmokeImage.ID, node)) {
    if (
      node.item.attributes.caption !== "Keep the caption" ||
      node.item.attributes.image !== null
    ) {
      throw new Error("The existing image block did not match the expected draft state.");
    }
    imageBlockCount += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.HostSmokeImage>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }

  return node;
});

if (helloCount !== 1 || imageBlockCount !== 1) {
  throw new Error("Expected exactly one target span and one image block.");
}

english.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

await client.items.update<Schema.HostSmokeArticle>(recordId, {
  body: {
    ...before.body,
    en: english,
  },
});

console.log(JSON.stringify({
  mutation: "completed-once",
  snapshot: beforeSnapshot,
  targetCounts: { helloCount, imageBlockCount },
}));

const recordId = "<dato-id-40>";
const expectedImageBlockId = "<dato-id-43>";

const after = await client.items.find<Schema.HostSmokeArticle>(recordId, {
  nested: true,
});

if (!after.body?.en || !after.body.it) {
  throw new Error("Expected English and Italian body values after update.");
}
if (after.title !== "Original title" || after.untouched !== "Keep this value") {
  throw new Error("A non-body field changed.");
}
if (
  after.meta.status !== "draft" ||
  after.meta.published_at !== null ||
  after.meta.first_published_at !== null
) {
  throw new Error("Publication state changed.");
}

const english = after.body.en;
if (english.document.children.length !== 3) {
  throw new Error("English root must contain the original two nodes plus one final paragraph.");
}

const first = english.document.children[0];
if (!isParagraph(first) || first.children.length !== 3) {
  throw new Error("The original English paragraph structure changed.");
}
const welcome = first.children[0];
const space = first.children[1];
const link = first.children[2];
if (
  !isSpan(welcome) ||
  welcome.value !== "Welcome reader" ||
  welcome.marks?.length !== 1 ||
  welcome.marks[0] !== "strong"
) {
  throw new Error("The requested English span change or its strong mark is incorrect.");
}
if (
  !isSpan(space) ||
  space.value !== " " ||
  (space.marks?.length ?? 0) !== 0
) {
  throw new Error("An untouched English span changed.");
}
if (
  !isLink(link) ||
  link.url !== "https://example.test/help" ||
  link.children.length !== 1
) {
  throw new Error("The preserved English link changed.");
}
const linkText = link.children[0];
if (
  !isSpan(linkText) ||
  linkText.value !== "Help" ||
  (linkText.marks?.length ?? 0) !== 0 ||
  (link.meta?.length ?? 0) !== 0
) {
  throw new Error("The preserved English link text or metadata changed.");
}

const imageNode = english.document.children[1];
if (!isBlockWithItemOfType(Schema.HostSmokeImage.ID, imageNode)) {
  throw new Error("The existing image block moved or changed type.");
}
if (
  imageNode.item.id !== expectedImageBlockId ||
  imageNode.item.attributes.caption !== "Summer portrait" ||
  imageNode.item.attributes.image !== null
) {
  throw new Error("The image block ID, caption, or null image value is incorrect.");
}

const finalNode = english.document.children[2];
if (
  !isParagraph(finalNode) ||
  finalNode.children.length !== 1 ||
  !isSpan(finalNode.children[0]) ||
  finalNode.children[0].value !== "See you soon." ||
  (finalNode.children[0].marks?.length ?? 0) !== 0
) {
  throw new Error("The final English paragraph is incorrect.");
}

const italian = after.body.it;
if (
  italian.document.children.length !== 1 ||
  !isParagraph(italian.document.children[0]) ||
  italian.document.children[0].children.length !== 1 ||
  !isSpan(italian.document.children[0].children[0]) ||
  italian.document.children[0].children[0].value !== "Ciao lettore" ||
  (italian.document.children[0].children[0].marks?.length ?? 0) !== 0
) {
  throw new Error("The complete Italian body changed.");
}

const locales = Object.keys(after.body).sort();
if (locales.length !== 2 || locales[0] !== "en" || locales[1] !== "it") {
  throw new Error("The body locale set changed.");
}

console.log("verification-passed: requested changes, preserved nodes/locales/fields, and draft state");
